class SearchPage(private val page: Page) {
    private val input: Locator = page.locator("[aria-label='Enter your search term']")

    fun navigate() { page.navigate("https://bing.com") }
    fun search(text: String) {
        input.fill(text)
        input.press("Enter")
    }
}
